    # Keep track of visited nodes to avoid reprocessing
    visited = set()

    # Keep track of the path from start to current node
    def search(graph, start, goal, path=[]):
        path = path + [start]
        if start == goal:
            return path
        if start not in visited:
            visited.add(start)
            for node in graph[start]:
                if node not in visited:
                    new_path = search(graph, node, goal, path)
                    if new_path:
                        return new_path
        return None

    # Start the search
