def find_path(graph, start, goal):
    def dfs(node, path):
        # If the current node is the goal, return the path
        if node == goal:
            return path + [goal]
        # If the current node is not in the visited set, mark it as visited and explore its neighbors
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    result = dfs(neighbor, path + [node])
                    if result:
                        return result
            # If no path is found, backtrack
            visited.remove(node)
        return None

    if start not in graph or goal not in graph:
        return None

    visited = set()
    return dfs(start, [start])

