def find_path(graph, start, goal):
    if start == goal:
        return [start]  # If start and goal are the same, return a list containing just that node.

    visited = set()
    queue = deque([(start, [start])])  # Each tuple in the queue contains a node and the path going through this node.

    while queue:
        (current_node, path) = queue.popleft()
        visited.add(current_node)

