def find_path(graph, start, goal):
    # Helper function to perform DFS
    def dfs(node, path, visited):
        if node == goal:
            return path + [node]
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                result = dfs(neighbor, path + [node], visited)
                if result:
