    def find_path_recursive(graph, node, visited, path, goal):
        visited.add(node)
        path.append(node)

        if node == goal:
            return path

        for next_node in graph.get(node, []):
            if next_node not in visited:
                result = find_path_recursive(graph, next_node, visited, path, goal)
                if result:
